package io.github.juliarezende521.workjourney.contract;
import io.github.juliarezende521.workjourney.journey.api.MarkingRequestReader;import jakarta.servlet.http.HttpServletRequest;import java.io.IOException;import java.time.LocalDate;import java.util.Set;import org.springframework.context.annotation.Profile;import org.springframework.http.HttpStatus;import org.springframework.web.bind.annotation.*;
@RestController @Profile("!bootstrap") public class EmploymentContractController{
    private final EmploymentContractService service;private final ContractRequestReader reader;private final MarkingRequestReader uuids;
    EmploymentContractController(EmploymentContractService service,ContractRequestReader reader,MarkingRequestReader uuids){this.service=service;this.reader=reader;this.uuids=uuids;}
    @GetMapping("/api/hr/employees/{employeeId}/employment-contract") EmploymentContractService.View current(@PathVariable String employeeId,HttpServletRequest request){exact(request,Set.of("on"));LocalDate on=null;try{if(request.getParameter("on")!=null)on=LocalDate.parse(request.getParameter("on"));}catch(RuntimeException invalid){throw new InvalidContract();}return service.currentForHr(uuids.uuid(employeeId),on);}
    @GetMapping("/api/hr/employees/{employeeId}/employment-contracts") EmploymentContractService.Page history(@PathVariable String employeeId,HttpServletRequest request){exact(request,Set.of("page","size"));return service.history(uuids.uuid(employeeId),integer(request,"page",0),integer(request,"size",20));}
    @PostMapping(value="/api/hr/employees/{employeeId}/employment-contracts",consumes="application/json") @ResponseStatus(HttpStatus.CREATED) EmploymentContractService.View create(@PathVariable String employeeId,HttpServletRequest request)throws IOException{var value=reader.read(request);return service.create(uuids.uuid(employeeId),value.effectiveFrom(),value.countryCode(),value.type(),value.weeklyMinutes());}
    private void exact(HttpServletRequest request,Set<String> allowed){var parameters=request.getParameterMap();if(!allowed.containsAll(parameters.keySet())||parameters.values().stream().anyMatch(values->values.length!=1))throw new InvalidContract();}
    private int integer(HttpServletRequest request,String name,int fallback){try{return request.getParameter(name)==null?fallback:Integer.parseInt(request.getParameter(name));}catch(NumberFormatException invalid){throw new InvalidContract();}}
}
